      es: ["Zoológico más importante de la provincia de Québec", "Hogar de más de 1.500 animales", "Parque acuático integrado Amazoo", "Fuerte compromiso con la conservación de especies"],
      pt: ["Zoológico mais importante da província de Québec", "Abriga mais de 1.500 animais", "Parque aquático integrado Amazoo", "Forte compromisso com a conservação de espécies"],
